"use client";

import * as React from "react";

import { cn, titleIfClamped } from "../lib/utils";

import styles from "./name-line.module.css";

/** One line of media, name, badges and trailing content. Under pressure the badges give way first (use Badge collapse), then a long name truncates to a 12ch floor, then the badges clip; the trailing content always stays whole. The full name shows on hover, or title when given, such as an unabbreviated value. */
export function NameLine({
  media,
  badges,
  trailing,
  children,
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  /** A leading icon, logo or avatar. */
  media?: React.ReactNode;
  /** Badges after the name; give each one collapse so they shrink before the name does. */
  badges?: React.ReactNode;
  /** Short content held whole at the line's end, such as a time or a count. */
  trailing?: React.ReactNode;
} & { ref?: React.Ref<HTMLDivElement> }) {
  const nameRef = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const name = nameRef.current;
    if (!name) return;
    const measure = () => {
      if ((name.textContent ?? "").length > 12) name.setAttribute("data-floor", "");
      else name.removeAttribute("data-floor");
    };
    measure();
    const observer = new MutationObserver(measure);
    observer.observe(name, {
      subtree: true,
      childList: true,
      characterData: true
    });
    return () => observer.disconnect();
  }, []);
  return (
    <div ref={ref} data-slot="name-line" className={cn(styles.line, className)} {...props}>
      <span className={styles.main}>
        {media && (
          <span data-slot="name-line-media" className={styles.media}>
            {media}
          </span>
        )}
        <span
          data-slot="name-line-name"
          ref={nameRef}
          className={styles.name}
          onPointerEnter={
            props.title === undefined ? (event) => titleIfClamped(event.currentTarget) : undefined
          }
        >
          {children}
        </span>
        {badges && <span className={styles.badges}>{badges}</span>}
      </span>
      {trailing && (
        <span data-slot="name-line-trailing" className={styles.trailing}>
          {trailing}
        </span>
      )}
    </div>
  );
}
NameLine.displayName = "NameLine";

.line {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  min-width: 0;
  max-width: 100%;
}
.main {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: var(--cipher-space-8);
  min-width: 0;
  overflow: hidden;
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
}
.media {
  display: inline-flex;
  flex: none;
  align-items: center;
}
.name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
}
.name[data-floor] {
  min-width: min(100%, 12ch);
}
.badges {
  display: contents;
}
.trailing {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-4);
  color: var(--cipher-muted);
}
